 17	  if (interval) {
 18	    return { primary: interval, secondary: null as string | null };
 19	  }
 20	
 21	  if (/^good$/i.test(label.trim())) {
 22	    return { primary: "✓", secondary: "Cram" };
 23	  }
 24	
 25	  return { primary: fallback, secondary: null as string | null };
 26	}
