 83	function isEditableTarget(target: EventTarget | null) {
 84	  const el = target as HTMLElement | null;
 85	  const root = el && el.nodeType === Node.ELEMENT_NODE ? el : null;
 86	  const editable =
 87	    Boolean(root?.isContentEditable) ||
 88	    Boolean(
 89	      root?.closest?.(
 90	        'input, textarea, select, [contenteditable="true"], [contenteditable=""], [contenteditable="plaintext-only"]',
 91	      ),
 92	    );
 93	  return editable;
 94	}
