 96	function useStudyCardPreviewModel({
 97	  card,
 98	  onBack,
 99	  onEdit,
100	}: {
101	  card: Card | null;
102	  onBack: () => void;
103	  onEdit?: () => void;
104	}) {
105	  const [flipped, setFlipped] = React.useState(false);
106	
107	  const flip = React.useCallback(() => setFlipped((value) => !value), []);
108	
109	  React.useEffect(() => {
110	    setFlipped(false);
111	  }, [card?.id, card?.question, card?.answer]);
112	
113	  const questionHtml = contentToSafeHtml(card?.question ?? "", "display");
114	  const answerHtml = contentToSafeHtml(card?.answer ?? "", "display");
115	  const cardTimeMeta = card ? formatStudyTimeBreakdown(card) : null;
116	
117	  React.useEffect(() => {
118	    const onKeyDown = (event: KeyboardEvent) => {
119	      if (isEditableTarget(event.target)) return;
120	      if (event.metaKey || event.ctrlKey || event.altKey) return;
121	
122	      if (event.key === "Escape") {
123	        event.preventDefault();
124	        onBack();
125	        return;
126	      }
127	
128	      if (event.key === " ") {
129	        event.preventDefault();
130	        flip();
131	        return;
132	      }
133	
134	      if (event.key.toLowerCase() === "e" && onEdit) {
135	        event.preventDefault();
136	        onEdit();
137	      }
138	    };
139	
140	    window.addEventListener("keydown", onKeyDown);
141	    return () => window.removeEventListener("keydown", onKeyDown);
142	  }, [flip, onBack, onEdit]);
143	
144	  return {
145	    answerHtml,
146	    cardTimeMeta,
147	    flip,
148	    flipped,
149	    questionHtml,
150	  };
151	}
