  92	function formatDelayedRepeatWait(dueAt: string, nowMs: number) {
  93	  const dueAtMs = Date.parse(dueAt);
  94	  if (!Number.isFinite(dueAtMs)) return "soon";
  95	  const remainingMinutes = Math.max(0, Math.ceil((dueAtMs - nowMs) / 60_000));
  96	  return formatStudyInterval(remainingMinutes);
  97	}
