  99	function useDeckMobileViewport() {
 100	  const [mobile, setMobile] = React.useState(false);
 101	
 102	  React.useEffect(() => {
 103	    if (typeof window === "undefined" || typeof window.matchMedia !== "function") return;
 104	    const media = window.matchMedia("(min-width: 1024px)");
 105	    if (!media) return;
 106	    const sync = () => setMobile(!media.matches);
 107	    sync();
 108	    media.addEventListener?.("change", sync);
 109	    media.addListener?.(sync);
 110	    return () => {
 111	      media.removeEventListener?.("change", sync);
 112	      media.removeListener?.(sync);
 113	    };
 114	  }, []);
 115	
 116	  return mobile;
 117	}
